 static void Capture(int pid,string output){
  var process=Supported(pid);long image=process.MainModule.BaseAddress.ToInt64();IntPtr h=OpenProcess(0x410,false,pid);Check(h!=IntPtr.Zero,"Open read-only Viper status");
  try{byte[] redirect=Read(h,image+0x772d10,5);if(redirect[0]!=0xe9)throw new Exception("Viper combat helper is not attached");long cave=image+0x772d10+5+BitConverter.ToInt32(redirect,1);byte[] code=BuildCave(image,cave);if(!Equal(Read(h,cave,code.Length),code))throw new Exception("A different Viper helper occupies the update entry");byte[] c=Read(h,cave+0x8000,3144);if(BitConverter.ToUInt32(c,44)!=0x56495032)throw new Exception("Viper configuration marker differs");var actors=new List<object>();for(int i=0;i<128;i++){int at=72+i*24;long actor=BitConverter.ToInt64(c,at);if(actor==0)continue;actors.Add(new {pointer=actor.ToString("x"),serial=BitConverter.ToUInt32(c,at+8),native_death_seen=BitConverter.ToUInt32(c,at+12)!=0,native_completion_seen=BitConverter.ToUInt32(c,at+16)!=0});}string stage=System.Text.Encoding.ASCII.GetString(Read(h,image+0x1535830,8)).Split((char)0)[0];string seed="unknown";string manifest=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"..","manifest.json");if(File.Exists(manifest)){var m=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(manifest));if(m.ContainsKey("seed"))seed=Convert.ToString(m["seed"]);}var report=new {format=1,seed=seed,arena=stage,helper="ViperCombatAdapter",read_only=true,spawns=BitConverter.ToUInt32(c,48),repositions=BitConverter.ToUInt32(c,52),flight_redirects=BitConverter.ToUInt32(c,56),native_completions_observed=BitConverter.ToUInt32(c,60),actors=actors};File.WriteAllText(output,new JavaScriptSerializer().Serialize(report));Console.WriteLine("Read-only Viper status captured: "+output);
  }finally{CloseHandle(h);}
 }
 static void SelfTest(string folder){Directory.CreateDirectory(folder);foreach(long image in new long[]{ImageBase,0x180000000,0x7ff600000000})foreach(long offset in new long[]{0x20000000,0x20010000,0x60000000}){long cave=image+offset;byte[] b=BuildCave(image,cave),c=Config(image);if(c.Length!=3144||b.Length>=0x8000)throw new Exception("Viper payload bounds");File.WriteAllBytes(Path.Combine(folder,"viper-"+image.ToString("x")+"-"+offset.ToString("x")+".bin"),b);File.WriteAllBytes(Path.Combine(folder,"config-"+image.ToString("x")+".bin"),c);}Console.WriteLine("Viper payload fixtures at three bases and three cave offsets; no game opened.");}
 public static int Main(string[] args){try{if(args.Length==2&&args[0]=="--self-test"){SelfTest(args[1]);return 0;}if(args.Length==2&&args[0]=="--attach-menu"){Attach(Int32.Parse(args[1]));return 0;}if(args.Length==3&&args[0]=="--capture-status"){Capture(Int32.Parse(args[1]),args[2]);return 0;}Console.WriteLine("--self-test folder; --attach-menu PID; --capture-status PID output.json");return 0;}catch(Exception ex){Console.Error.WriteLine(ex.Message);return 1;}}
}
